"""Column addition, one column at a time: the carries above, the two numbers, the line,
and the sum's digits as they are written. Step adds the next column; the picture is
drawn in its Paint event from the state (the columns done and the carries)."""

from vp6 import *

CELL = 34  # (a column's width on the picture)
PLACE_NAMES = ("ones", "tens", "hundreds", "thousands", "ten thousands", "hundred thousands",
               "millions", "ten millions", "hundred millions", "billions")


class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Column Addition'
        self.Width = 560
        self.Height = 420
        self.lblA = Label(self, Caption='First number:', Left=16, Top=18, Width=110, Height=24,
                          TabIndex=1)
        self.txtA = TextBox(self, Text='4587', Left=130, Top=14, Width=150, Height=28, TabIndex=2)
        self.lblB = Label(self, Caption='Second number:', Left=16, Top=54, Width=110, Height=24,
                          TabIndex=3)
        self.txtB = TextBox(self, Text='2946', Left=130, Top=50, Width=150, Height=28, TabIndex=4)
        self.cmdStep = CommandButton(self, Caption='&Step', Left=300, Top=14, Width=110, Height=32,
                                     Default=True, TabIndex=5)
        self.cmdRestart = CommandButton(self, Caption='&Restart', Left=300, Top=50, Width=110,
                                        Height=32, TabIndex=6)
        self.picWork = PictureBox(self, Left=16, Top=96, Width=520, Height=200, BackColor=0xFAFFFF,
                                  FontSize=20, TabIndex=7)
        self.lblExplain = Label(self, Caption='', Left=16, Top=306, Width=520, Height=60,
                                WordWrap=True, TabIndex=8)
    # endregion

    a = b = 0
    done = 0  # (the columns added so far)
    carries: dict = {}  # (column: the carry into it)
    digits: dict = {}  # (column: the sum's digit written there)

    def Form_Load(self):
        self.restart()

    def txtA_Change(self):
        self.restart()

    def txtB_Change(self):
        self.restart()

    def cmdRestart_Click(self):
        self.restart()

    def restart(self):
        """Read the two numbers and start again at the ones."""
        a, b = self.txtA.Text.replace(",", "").strip(), self.txtB.Text.replace(",", "").strip()
        self.done, self.carries, self.digits = 0, {}, {}
        if not (a.isdigit() and b.isdigit()):
            self.a = self.b = 0
            self.cmdStep.Enabled = False
            self.lblExplain.Caption = "Type two whole numbers."
        else:
            self.a, self.b = int(a), int(b)
            self.cmdStep.Enabled = True
            self.lblExplain.Caption = "Press Step to add the ones column."
        self.picWork.Refresh()

    def columns(self):
        return len(str(max(self.a, self.b)))

    def cmdStep_Click(self):
        self.step()

    def step(self):
        """Add the next column: its two digits and the carry into it."""
        column = self.done
        x, y = self.a // 10 ** column % 10, self.b // 10 ** column % 10
        carry = self.carries.get(column, 0)
        total = x + y + carry
        self.digits[column] = total % 10
        if total >= 10:
            self.carries[column + 1] = 1
        self.done += 1
        place = PLACE_NAMES[min(column, len(PLACE_NAMES) - 1)]
        added = " + ".join(str(v) for v in ([carry] if carry else []) + [x, y])
        text = f"The {place}: {added} = {total}. Write {total % 10}"
        text += ", carry 1 into the next column." if total >= 10 else "."
        if self.done >= self.columns() and column + 1 not in self.carries:
            self.cmdStep.Enabled = False
            text += f"  Done: {self.a:,} + {self.b:,} = {self.a + self.b:,}."
        elif self.done >= self.columns():  # (the last carry makes a new column)
            self.digits[self.done] = 1
            self.done += 1
            self.cmdStep.Enabled = False
            text += f"  The carry is the sum's first digit: {self.a + self.b:,}."
        self.lblExplain.Caption = text
        self.picWork.Refresh()

    def picWork_Paint(self):
        pic = self.picWork
        width = self.columns() + 2
        right = pic.ScaleWidth - 20

        def cell(column, row, text, color):
            x = right - (column + 1) * CELL
            pic.ForeColor = color
            pic.DrawText(text, x, 8 + row * 44, x + CELL, 8 + (row + 1) * 44)

        if self.done < self.columns():  # (the column being added, shaded)
            x = right - (self.done + 1) * CELL
            pic.Line(x, 4, x + CELL - 1, 4 + 4 * 44, RGB(255, 236, 160), "BF")  # (on paper:
            # the picture is white, light or dark)
        for column, carry in self.carries.items():
            pic.FontSize = 12
            cell(column, 0, str(carry), RGB(200, 60, 40))
        pic.FontSize = 20
        for row, number in ((1, self.a), (2, self.b)):
            for column, digit in enumerate(reversed(str(number))):
                cell(column, row, digit, RGB(30, 30, 30))
        cell(width - 1, 2, "+", RGB(30, 30, 30))
        pic.Line(right - width * CELL, 8 + 3 * 44, right, 8 + 3 * 44, RGB(30, 30, 30))
        for column, digit in self.digits.items():
            cell(column, 3, str(digit), RGB(30, 110, 200))


if __name__ == "__main__":
    run(Form1)
